BEGIN;
CREATE TABLE readings(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,device_id text,sampled_at_ms bigint,temperature_c numeric,humidity_pct numeric,water_low boolean,light_pct numeric,moisture_pct numeric,pump_on boolean,is_test boolean,received_at timestamptz DEFAULT now());
CREATE TABLE watering_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,device_id text,boot_id text,cycle_id bigint,event text,occurred_at_ms bigint,duration_ms bigint,reason text,is_test boolean,received_at timestamptz DEFAULT now(),UNIQUE(device_id,boot_id,cycle_id,event));
