DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=4 FROM readings),false) THEN RAISE EXCEPTION 'FAILED: backend INSERT fixtures store four readings'; END IF; RAISE NOTICE 'PASS: backend INSERT fixtures store four readings'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=2 FROM watering_events),false) THEN RAISE EXCEPTION 'FAILED: backend ON CONFLICT keeps one start and one stop for a repeated cycle'; END IF; RAISE NOTICE 'PASS: backend ON CONFLICT keeps one start and one stop for a repeated cycle'; END $$;
TRUNCATE readings,watering_events;
