DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT temperature_c AS "Temperature" FROM readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 1 executes with expected row count in Real'; END IF; RAISE NOTICE 'PASS: panel 1 executes with expected row count in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT humidity_pct AS "Humidity" FROM readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 2 executes with expected row count in Real'; END IF; RAISE NOTICE 'PASS: panel 2 executes with expected row count in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT light_pct AS "Relative light" FROM readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 3 executes with expected row count in Real'; END IF; RAISE NOTICE 'PASS: panel 3 executes with expected row count in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT moisture_pct AS "Relative soil moisture" FROM readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 4 executes with expected row count in Real'; END IF; RAISE NOTICE 'PASS: panel 4 executes with expected row count in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT water_low::integer AS "Reservoir" FROM readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 5 executes with expected row count in Real'; END IF; RAISE NOTICE 'PASS: panel 5 executes with expected row count in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT pump_on::integer AS "Pump command" FROM readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 6 executes with expected row count in Real'; END IF; RAISE NOTICE 'PASS: panel 6 executes with expected row count in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT GREATEST(0, EXTRACT(EPOCH FROM (now() - received_at))) AS "Seconds since last reading" FROM readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 7 executes with expected row count in Real'; END IF; RAISE NOTICE 'PASS: panel 7 executes with expected row count in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT received_at AS "Last received", device_id AS "Device", sampled_at_ms AS "Sample uptime (ms)", CASE WHEN is_test THEN 'TEST DATA' ELSE 'REAL DATA' END AS "Data mode" FROM readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 8 executes with expected row count in Real'; END IF; RAISE NOTICE 'PASS: panel 8 executes with expected row count in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=6 FROM (WITH latest AS ( SELECT received_at, temperature_c, humidity_pct, water_low, moisture_pct, pump_on FROM public.readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1 ), state AS ( SELECT latest.*, COALESCE(received_at >= now() - interval '30 seconds', false) AS fresh FROM (VALUES (1)) AS seed(n) LEFT JOIN latest ON true ) SELECT checks.name AS "Check", checks.status AS "Status" FROM state CROSS JOIN LATERAL (VALUES (1, 'Incoming data', CASE WHEN received_at IS NULL THEN 'NO DATA — no readings received' WHEN NOT fresh THEN 'STALE — check device and connection' ELSE 'OK' END), (2, 'Reservoir', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN water_low IS NULL THEN 'FAULT — reservoir sensor' WHEN water_low THEN 'LOW WATER — refill reservoir' ELSE 'OK' END), (3, 'Temperature', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN temperature_c IS NULL THEN 'FAULT — temperature sensor' WHEN temperature_c < 16 THEN 'LOW — below 16°C' WHEN temperature_c > 27 THEN 'HIGH — above 27°C' ELSE 'OK' END), (4, 'Humidity', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN humidity_pct IS NULL THEN 'FAULT — humidity sensor' WHEN humidity_pct < 40 THEN 'LOW — below 40%' WHEN humidity_pct > 60 THEN 'HIGH — above 60%' ELSE 'OK' END), (5, 'Soil sensor', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN moisture_pct IS NULL THEN 'FAULT — soil sensor' ELSE 'OK' END), (6, 'Pump status', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN pump_on IS NULL THEN 'FAULT — pump status unavailable' ELSE 'OK' END) ) AS checks(position, name, status) ORDER BY checks.position) q),false) THEN RAISE EXCEPTION 'FAILED: panel 14 executes with expected row count in Real'; END IF; RAISE NOTICE 'PASS: panel 14 executes with expected row count in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=3 FROM (SELECT received_at AS "time", temperature_c AS "Temperature" FROM readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') AND received_at BETWEEN now()-interval '1 day' AND now()+interval '1 hour' ORDER BY received_at, id) q),false) THEN RAISE EXCEPTION 'FAILED: panel 9 executes with expected row count in Real'; END IF; RAISE NOTICE 'PASS: panel 9 executes with expected row count in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=3 FROM (SELECT received_at AS "time", humidity_pct AS "Humidity" FROM readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') AND received_at BETWEEN now()-interval '1 day' AND now()+interval '1 hour' ORDER BY received_at, id) q),false) THEN RAISE EXCEPTION 'FAILED: panel 10 executes with expected row count in Real'; END IF; RAISE NOTICE 'PASS: panel 10 executes with expected row count in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=3 FROM (SELECT received_at AS "time", light_pct AS "Relative light" FROM readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') AND received_at BETWEEN now()-interval '1 day' AND now()+interval '1 hour' ORDER BY received_at, id) q),false) THEN RAISE EXCEPTION 'FAILED: panel 11 executes with expected row count in Real'; END IF; RAISE NOTICE 'PASS: panel 11 executes with expected row count in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=3 FROM (SELECT received_at AS "time", moisture_pct AS "Relative soil moisture" FROM readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') AND received_at BETWEEN now()-interval '1 day' AND now()+interval '1 hour' ORDER BY received_at, id) q),false) THEN RAISE EXCEPTION 'FAILED: panel 12 executes with expected row count in Real'; END IF; RAISE NOTICE 'PASS: panel 12 executes with expected row count in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=6 FROM (SELECT received_at AS "Received", CASE event WHEN 'started' THEN 'Started' WHEN 'stopped' THEN 'Stopped' ELSE event END AS "Action", duration_ms / 1000.0 AS "Duration", CASE reason WHEN 'dry_soil' THEN 'Dry soil' WHEN 'time_limit' THEN 'Time limit reached' WHEN 'soil_wet' THEN 'Soil no longer dry' WHEN 'low_water' THEN 'Low reservoir' WHEN 'invalid_sensor' THEN 'Sensor fault' ELSE reason END AS "Reason" FROM public.watering_events WHERE device_id = '01' AND is_test = ('Real' = 'Test') AND received_at BETWEEN now()-interval '1 day' AND now()+interval '1 hour' ORDER BY MAX(received_at) OVER (PARTITION BY boot_id) DESC, boot_id, cycle_id DESC, occurred_at_ms ASC, id ASC LIMIT 500) q),false) THEN RAISE EXCEPTION 'FAILED: panel 13 executes with expected row count in Real'; END IF; RAISE NOTICE 'PASS: panel 13 executes with expected row count in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT "Temperature"=24 FROM (SELECT temperature_c AS "Temperature" FROM readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: latest value and tie break in Real'; END IF; RAISE NOTICE 'PASS: latest value and tie break in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT min("Temperature")=22 AND max("Temperature")=24 FROM (SELECT received_at AS "time", temperature_c AS "Temperature" FROM readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') AND received_at BETWEEN now()-interval '1 day' AND now()+interval '1 hour' ORDER BY received_at, id) q),false) THEN RAISE EXCEPTION 'FAILED: history values stay in Real'; END IF; RAISE NOTICE 'PASS: history values stay in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT array_agg("Action")=ARRAY['Started','Stopped','Started','Stopped','Started','Stopped'] AND count(*) FILTER (WHERE "Duration"=2)=3 FROM (SELECT received_at AS "Received", CASE event WHEN 'started' THEN 'Started' WHEN 'stopped' THEN 'Stopped' ELSE event END AS "Action", duration_ms / 1000.0 AS "Duration", CASE reason WHEN 'dry_soil' THEN 'Dry soil' WHEN 'time_limit' THEN 'Time limit reached' WHEN 'soil_wet' THEN 'Soil no longer dry' WHEN 'low_water' THEN 'Low reservoir' WHEN 'invalid_sensor' THEN 'Sensor fault' ELSE reason END AS "Reason" FROM public.watering_events WHERE device_id = '01' AND is_test = ('Real' = 'Test') AND received_at BETWEEN now()-interval '1 day' AND now()+interval '1 hour' ORDER BY MAX(received_at) OVER (PARTITION BY boot_id) DESC, boot_id, cycle_id DESC, occurred_at_ms ASC, id ASC LIMIT 500) q),false) THEN RAISE EXCEPTION 'FAILED: watering start stop order in Real'; END IF; RAISE NOTICE 'PASS: watering start stop order in Real'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT temperature_c AS "Temperature" FROM readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 1 executes with expected row count in Test'; END IF; RAISE NOTICE 'PASS: panel 1 executes with expected row count in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT humidity_pct AS "Humidity" FROM readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 2 executes with expected row count in Test'; END IF; RAISE NOTICE 'PASS: panel 2 executes with expected row count in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT light_pct AS "Relative light" FROM readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 3 executes with expected row count in Test'; END IF; RAISE NOTICE 'PASS: panel 3 executes with expected row count in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT moisture_pct AS "Relative soil moisture" FROM readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 4 executes with expected row count in Test'; END IF; RAISE NOTICE 'PASS: panel 4 executes with expected row count in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT water_low::integer AS "Reservoir" FROM readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 5 executes with expected row count in Test'; END IF; RAISE NOTICE 'PASS: panel 5 executes with expected row count in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT pump_on::integer AS "Pump command" FROM readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 6 executes with expected row count in Test'; END IF; RAISE NOTICE 'PASS: panel 6 executes with expected row count in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT GREATEST(0, EXTRACT(EPOCH FROM (now() - received_at))) AS "Seconds since last reading" FROM readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 7 executes with expected row count in Test'; END IF; RAISE NOTICE 'PASS: panel 7 executes with expected row count in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=1 FROM (SELECT received_at AS "Last received", device_id AS "Device", sampled_at_ms AS "Sample uptime (ms)", CASE WHEN is_test THEN 'TEST DATA' ELSE 'REAL DATA' END AS "Data mode" FROM readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: panel 8 executes with expected row count in Test'; END IF; RAISE NOTICE 'PASS: panel 8 executes with expected row count in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=6 FROM (WITH latest AS ( SELECT received_at, temperature_c, humidity_pct, water_low, moisture_pct, pump_on FROM public.readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1 ), state AS ( SELECT latest.*, COALESCE(received_at >= now() - interval '30 seconds', false) AS fresh FROM (VALUES (1)) AS seed(n) LEFT JOIN latest ON true ) SELECT checks.name AS "Check", checks.status AS "Status" FROM state CROSS JOIN LATERAL (VALUES (1, 'Incoming data', CASE WHEN received_at IS NULL THEN 'NO DATA — no readings received' WHEN NOT fresh THEN 'STALE — check device and connection' ELSE 'OK' END), (2, 'Reservoir', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN water_low IS NULL THEN 'FAULT — reservoir sensor' WHEN water_low THEN 'LOW WATER — refill reservoir' ELSE 'OK' END), (3, 'Temperature', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN temperature_c IS NULL THEN 'FAULT — temperature sensor' WHEN temperature_c < 16 THEN 'LOW — below 16°C' WHEN temperature_c > 27 THEN 'HIGH — above 27°C' ELSE 'OK' END), (4, 'Humidity', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN humidity_pct IS NULL THEN 'FAULT — humidity sensor' WHEN humidity_pct < 40 THEN 'LOW — below 40%' WHEN humidity_pct > 60 THEN 'HIGH — above 60%' ELSE 'OK' END), (5, 'Soil sensor', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN moisture_pct IS NULL THEN 'FAULT — soil sensor' ELSE 'OK' END), (6, 'Pump status', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN pump_on IS NULL THEN 'FAULT — pump status unavailable' ELSE 'OK' END) ) AS checks(position, name, status) ORDER BY checks.position) q),false) THEN RAISE EXCEPTION 'FAILED: panel 14 executes with expected row count in Test'; END IF; RAISE NOTICE 'PASS: panel 14 executes with expected row count in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=3 FROM (SELECT received_at AS "time", temperature_c AS "Temperature" FROM readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') AND received_at BETWEEN now()-interval '1 day' AND now()+interval '1 hour' ORDER BY received_at, id) q),false) THEN RAISE EXCEPTION 'FAILED: panel 9 executes with expected row count in Test'; END IF; RAISE NOTICE 'PASS: panel 9 executes with expected row count in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=3 FROM (SELECT received_at AS "time", humidity_pct AS "Humidity" FROM readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') AND received_at BETWEEN now()-interval '1 day' AND now()+interval '1 hour' ORDER BY received_at, id) q),false) THEN RAISE EXCEPTION 'FAILED: panel 10 executes with expected row count in Test'; END IF; RAISE NOTICE 'PASS: panel 10 executes with expected row count in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=3 FROM (SELECT received_at AS "time", light_pct AS "Relative light" FROM readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') AND received_at BETWEEN now()-interval '1 day' AND now()+interval '1 hour' ORDER BY received_at, id) q),false) THEN RAISE EXCEPTION 'FAILED: panel 11 executes with expected row count in Test'; END IF; RAISE NOTICE 'PASS: panel 11 executes with expected row count in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=3 FROM (SELECT received_at AS "time", moisture_pct AS "Relative soil moisture" FROM readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') AND received_at BETWEEN now()-interval '1 day' AND now()+interval '1 hour' ORDER BY received_at, id) q),false) THEN RAISE EXCEPTION 'FAILED: panel 12 executes with expected row count in Test'; END IF; RAISE NOTICE 'PASS: panel 12 executes with expected row count in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=6 FROM (SELECT received_at AS "Received", CASE event WHEN 'started' THEN 'Started' WHEN 'stopped' THEN 'Stopped' ELSE event END AS "Action", duration_ms / 1000.0 AS "Duration", CASE reason WHEN 'dry_soil' THEN 'Dry soil' WHEN 'time_limit' THEN 'Time limit reached' WHEN 'soil_wet' THEN 'Soil no longer dry' WHEN 'low_water' THEN 'Low reservoir' WHEN 'invalid_sensor' THEN 'Sensor fault' ELSE reason END AS "Reason" FROM public.watering_events WHERE device_id = '01' AND is_test = ('Test' = 'Test') AND received_at BETWEEN now()-interval '1 day' AND now()+interval '1 hour' ORDER BY MAX(received_at) OVER (PARTITION BY boot_id) DESC, boot_id, cycle_id DESC, occurred_at_ms ASC, id ASC LIMIT 500) q),false) THEN RAISE EXCEPTION 'FAILED: panel 13 executes with expected row count in Test'; END IF; RAISE NOTICE 'PASS: panel 13 executes with expected row count in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT "Temperature"=26 FROM (SELECT temperature_c AS "Temperature" FROM readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1) q),false) THEN RAISE EXCEPTION 'FAILED: latest value and tie break in Test'; END IF; RAISE NOTICE 'PASS: latest value and tie break in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT min("Temperature")=24 AND max("Temperature")=26 FROM (SELECT received_at AS "time", temperature_c AS "Temperature" FROM readings WHERE device_id = '01' AND is_test = ('Test' = 'Test') AND received_at BETWEEN now()-interval '1 day' AND now()+interval '1 hour' ORDER BY received_at, id) q),false) THEN RAISE EXCEPTION 'FAILED: history values stay in Test'; END IF; RAISE NOTICE 'PASS: history values stay in Test'; END $$;
DO $$ BEGIN IF NOT COALESCE((SELECT array_agg("Action")=ARRAY['Started','Stopped','Started','Stopped','Started','Stopped'] AND count(*) FILTER (WHERE "Duration"=2)=3 FROM (SELECT received_at AS "Received", CASE event WHEN 'started' THEN 'Started' WHEN 'stopped' THEN 'Stopped' ELSE event END AS "Action", duration_ms / 1000.0 AS "Duration", CASE reason WHEN 'dry_soil' THEN 'Dry soil' WHEN 'time_limit' THEN 'Time limit reached' WHEN 'soil_wet' THEN 'Soil no longer dry' WHEN 'low_water' THEN 'Low reservoir' WHEN 'invalid_sensor' THEN 'Sensor fault' ELSE reason END AS "Reason" FROM public.watering_events WHERE device_id = '01' AND is_test = ('Test' = 'Test') AND received_at BETWEEN now()-interval '1 day' AND now()+interval '1 hour' ORDER BY MAX(received_at) OVER (PARTITION BY boot_id) DESC, boot_id, cycle_id DESC, occurred_at_ms ASC, id ASC LIMIT 500) q),false) THEN RAISE EXCEPTION 'FAILED: watering start stop order in Test'; END IF; RAISE NOTICE 'PASS: watering start stop order in Test'; END $$;
TRUNCATE readings;
INSERT INTO readings(device_id,sampled_at_ms,temperature_c,humidity_pct,water_low,light_pct,moisture_pct,pump_on,is_test,received_at) VALUES ('01',1000,16,40,false,50,50,false,false,now()-interval '0 seconds');
DO $$ BEGIN IF NOT COALESCE((SELECT bool_and("Status"='OK') FROM (WITH latest AS ( SELECT received_at, temperature_c, humidity_pct, water_low, moisture_pct, pump_on FROM public.readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1 ), state AS ( SELECT latest.*, COALESCE(received_at >= now() - interval '30 seconds', false) AS fresh FROM (VALUES (1)) AS seed(n) LEFT JOIN latest ON true ) SELECT checks.name AS "Check", checks.status AS "Status" FROM state CROSS JOIN LATERAL (VALUES (1, 'Incoming data', CASE WHEN received_at IS NULL THEN 'NO DATA — no readings received' WHEN NOT fresh THEN 'STALE — check device and connection' ELSE 'OK' END), (2, 'Reservoir', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN water_low IS NULL THEN 'FAULT — reservoir sensor' WHEN water_low THEN 'LOW WATER — refill reservoir' ELSE 'OK' END), (3, 'Temperature', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN temperature_c IS NULL THEN 'FAULT — temperature sensor' WHEN temperature_c < 16 THEN 'LOW — below 16°C' WHEN temperature_c > 27 THEN 'HIGH — above 27°C' ELSE 'OK' END), (4, 'Humidity', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN humidity_pct IS NULL THEN 'FAULT — humidity sensor' WHEN humidity_pct < 40 THEN 'LOW — below 40%' WHEN humidity_pct > 60 THEN 'HIGH — above 60%' ELSE 'OK' END), (5, 'Soil sensor', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN moisture_pct IS NULL THEN 'FAULT — soil sensor' ELSE 'OK' END), (6, 'Pump status', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN pump_on IS NULL THEN 'FAULT — pump status unavailable' ELSE 'OK' END) ) AS checks(position, name, status) ORDER BY checks.position) q),false) THEN RAISE EXCEPTION 'FAILED: normal inclusive boundaries 16C 40pct'; END IF; RAISE NOTICE 'PASS: normal inclusive boundaries 16C 40pct'; END $$;
