DO $$ BEGIN IF NOT COALESCE((SELECT count(*)=6 AND bool_and("Status"='OK') FROM (WITH latest AS ( SELECT received_at, temperature_c, humidity_pct, water_low, moisture_pct, pump_on FROM public.readings WHERE device_id = '01' AND is_test = ('Real' = 'Test') ORDER BY received_at DESC, id DESC LIMIT 1 ), state AS ( SELECT latest.*, COALESCE(received_at >= now() - interval '30 seconds', false) AS fresh FROM (VALUES (1)) AS seed(n) LEFT JOIN latest ON true ) SELECT checks.name AS "Check", checks.status AS "Status" FROM state CROSS JOIN LATERAL (VALUES (1, 'Incoming data', CASE WHEN received_at IS NULL THEN 'NO DATA — no readings received' WHEN NOT fresh THEN 'STALE — check device and connection' ELSE 'OK' END), (2, 'Reservoir', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN water_low IS NULL THEN 'FAULT — reservoir sensor' WHEN water_low THEN 'LOW WATER — refill reservoir' ELSE 'OK' END), (3, 'Temperature', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN temperature_c IS NULL THEN 'FAULT — temperature sensor' WHEN temperature_c < 16 THEN 'LOW — below 16°C' WHEN temperature_c > 27 THEN 'HIGH — above 27°C' ELSE 'OK' END), (4, 'Humidity', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN humidity_pct IS NULL THEN 'FAULT — humidity sensor' WHEN humidity_pct < 40 THEN 'LOW — below 40%' WHEN humidity_pct > 60 THEN 'HIGH — above 60%' ELSE 'OK' END), (5, 'Soil sensor', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN moisture_pct IS NULL THEN 'FAULT — soil sensor' ELSE 'OK' END), (6, 'Pump status', CASE WHEN NOT fresh THEN 'UNKNOWN — no fresh data' WHEN pump_on IS NULL THEN 'FAULT — pump status unavailable' ELSE 'OK' END) ) AS checks(position, name, status) ORDER BY checks.position) q),false) THEN RAISE EXCEPTION 'FAILED: no light warning even with light 0'; END IF; RAISE NOTICE 'PASS: no light warning even with light 0'; END $$;
